export type Messages = Record<string, string>

export function getMessages(locale: LocaleCode): Messages {
  if (locale === "ru" || locale === "ja") {
    const index = locale === "ru" ? 0 : 1
    return Object.fromEntries(Object.entries(RU_JA).map(([source, values]) => [source, values[index]]))
  }
  const index = locale === "en" ? 0 : locale === "de" ? 1 : locale === "es" ? 2 : locale === "fr" ? 3 : locale === "it" ? 4 : 5
  return Object.fromEntries(MESSAGE_ROWS.map((row) => [row[0], row[index]]))
}

export function formatMessage(messages: Messages, source: string, values?: Record<string, string | number>): string {
  let result = messages[source] ?? source
  for (const [key, value] of Object.entries(values ?? {})) result = result.split(`{${key}}`).join(String(value))
  return result
}
